import{_ as i,o as t,c as e,a2 as s}from"./chunks/framework.BqNd1sPY.js";const h=JSON.parse('{"title":"D21：模型卡、复现与成果验收","description":"","frontmatter":{},"headers":[],"relativePath":"02-第3周实战/D21-模型卡、复现与成果验收.md","filePath":"02-第3周实战/D21-模型卡、复现与成果验收.md"}'),r={name:"02-第3周实战/D21-模型卡、复现与成果验收.md"};function l(o,a,m,c,n,k){return t(),e("div",null,[...a[0]||(a[0]=[s('<h1 id="d21-模型卡、复现与成果验收" tabindex="-1">D21：模型卡、复现与成果验收 <a class="header-anchor" href="#d21-模型卡、复现与成果验收" aria-label="Permalink to &quot;D21：模型卡、复现与成果验收&quot;">​</a></h1><h2 id="整理交付" tabindex="-1">整理交付 <a class="header-anchor" href="#整理交付" aria-label="Permalink to &quot;整理交付&quot;">​</a></h2><p>填写 <a href="./模型卡模板">模型卡模板</a>，附上：</p><ul><li>代码版本或 Git commit。</li><li>环境报告。</li><li>使用的配置。</li><li>数据卡。</li><li>训练和验证 <a href="/LLMTrain/05-速查表/术语速查#term-loss" class="wiki-term" data-wiki-title="loss" data-wiki-summary="训练目标对应的误差标量，优化器尝试让它下降。" data-wiki-misconception="一个 loss 数值足以代表模型的全部质量。">loss</a>。</li><li>未训练、训练后和对照实验输出。</li><li>已知失败和不适用场景。</li></ul><h2 id="复现实验" tabindex="-1">复现实验 <a class="header-anchor" href="#复现实验" aria-label="Permalink to &quot;复现实验&quot;">​</a></h2><p>关闭终端后重新打开，只看 README，从创建环境开始执行 smoke 训练。能够在干净环境跑通，比“我电脑上有一个<a href="/LLMTrain/05-速查表/术语速查#term-checkpoint" class="wiki-term" data-wiki-title="checkpoint" data-wiki-summary="训练过程保存的权重及恢复训练所需状态快照。" data-wiki-misconception="checkpoint 天然就是可直接上线的完整产品。">检查点</a>”更有价值。</p><h2 id="最终口试" tabindex="-1">最终口试 <a class="header-anchor" href="#最终口试" aria-label="Permalink to &quot;最终口试&quot;">​</a></h2><ol><li>数据如何变成训练 <a href="/LLMTrain/05-速查表/术语速查#term-batch" class="wiki-term" data-wiki-title="batch" data-wiki-summary="一次前向与反向计算共同处理的一组样本。" data-wiki-misconception="一个 batch 必然等于一次优化器更新或整个数据集。">batch</a>？</li><li><a href="/LLMTrain/05-速查表/术语速查#term-causal-mask" class="wiki-term" data-wiki-title="causal mask" data-wiki-summary="在自回归训练中阻止当前位置读取未来 token 的遮罩。" data-wiki-misconception="它会阻止模型读取当前位置之前的内容。">因果遮罩</a>在代码哪里生效？</li><li><a href="/LLMTrain/05-速查表/术语速查#term-loss" class="wiki-term" data-wiki-title="loss" data-wiki-summary="训练目标对应的误差标量，优化器尝试让它下降。" data-wiki-misconception="一个 loss 数值足以代表模型的全部质量。">loss</a> 如何产生<a href="/LLMTrain/05-速查表/术语速查#term-gradient" class="wiki-term" data-wiki-title="gradient" data-wiki-summary="loss 对各参数的局部变化率，指出当前附近怎样调整会改变 loss。" data-wiki-misconception="梯度直接给出了全局最优答案。">梯度</a>？</li><li>训练 <a href="/LLMTrain/05-速查表/术语速查#term-loss" class="wiki-term" data-wiki-title="loss" data-wiki-summary="训练目标对应的误差标量，优化器尝试让它下降。" data-wiki-misconception="一个 loss 数值足以代表模型的全部质量。">loss</a> 与验证 <a href="/LLMTrain/05-速查表/术语速查#term-loss" class="wiki-term" data-wiki-title="loss" data-wiki-summary="训练目标对应的误差标量，优化器尝试让它下降。" data-wiki-misconception="一个 loss 数值足以代表模型的全部质量。">loss</a> 各说明什么？</li><li><a href="/LLMTrain/05-速查表/术语速查#term-checkpoint" class="wiki-term" data-wiki-title="checkpoint" data-wiki-summary="训练过程保存的权重及恢复训练所需状态快照。" data-wiki-misconception="checkpoint 天然就是可直接上线的完整产品。">检查点</a>需要哪些信息才能继续或复现？</li><li>为什么这个项目不是通用大语言模型？</li><li>若要扩展，先增加高质量数据、<a href="/LLMTrain/05-速查表/术语速查#term-parameter" class="wiki-term" data-wiki-title="parameter" data-wiki-summary="模型中由训练确定的数字；训练时只有未冻结的参数会被更新。" data-wiki-misconception="一个参数对应一条可直接读取的事实。">参数</a>量还是<a href="/LLMTrain/05-速查表/术语速查#term-step" class="wiki-term" data-wiki-title="step" data-wiki-summary="本课程默认指一次优化器更新；阅读日志时应先确认工具的定义。" data-wiki-misconception="所有框架里的 step 都代表完全相同的事件。">训练步</a>数，怎样设计对照？</li></ol><p>七题中至少六题能闭卷说明，并且 smoke 流程可复现，项目即完成。</p>',9)])])}const w=i(r,[["render",l]]);export{h as __pageData,w as default};
